import io
from werkzeug.formparser import FormDataParser
from werkzeug.wrappers import Request

class Fragmented(io.BytesIO):
    def read(self, size=-1):
        return super().read(min(size, 1) if size >= 0 else 1)
    def readinto(self, buffer):
        data = self.read(len(buffer))
        buffer[:len(data)] = data
        return len(data)

payload=b'\0\r\n--foo--X\r\n--foo----\r\n--foo-- \tX\r'
body=b''
for filename, value in [(None,b'first\0\r'),('a.bin',payload),(None,b''),('empty.bin',b'')]:
    body+=b'--foo \t\r\nContent-Disposition: form-data; name="x"'
    if filename is not None:
        body+=b'; filename="'+filename.encode()+b'"'
    body+=b'\r\nX-Test: retained\r\n\r\n'+value+b'\r\n'
body+=b'--foo-- \t'
for method in ['parser','request']:
    if method=='parser':
        _,form,files=FormDataParser(silent=False).parse(Fragmented(body),'multipart/form-data',len(body),{'boundary':'foo'})
    else:
        req=Request.from_values(input_stream=Fragmented(body),content_length=len(body),content_type='multipart/form-data; boundary=foo',method='POST')
        form,files=req.form,req.files
    assert form.getlist('x')==['first\0\r','']
    uploads=files.getlist('x')
    assert [f.filename for f in uploads]==['a.bin','empty.bin']
    assert [f.read() for f in uploads]==[payload,b'']
    assert all(f.headers['X-Test']=='retained' for f in uploads)
    for f in uploads: f.close()
    if method=='request': req.close()
print('one-byte FormDataParser and Request checks passed')
